draw:
var g = p.gravity, v0 = p.v0, h0 = p.h0;
var tf = (v0 + Math.sqrt(v0 * v0 + 2 * g * h0)) / g;
var peak = h0 + (v0 > 0 ? (v0 * v0) / (2 * g) : 0);
var top = Math.max(peak * 1.18, 4);
var pad = 24;
var groundY = H - pad;
var sc = (groundY - pad) / top;
function Y(y) { return groundY - y * sc; }
var cx = W * 0.34;

var cyc = tf + 0.9;
var now = t % cyc;
var tt = now < tf ? now : tf;
var y = h0 + v0 * tt - 0.5 * g * tt * tt;
if (y < 0) { y = 0; }
var v = v0 - g * tt;

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1;

ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(10, groundY); ctx.lineTo(W - 10, groundY); ctx.stroke();
ctx.fillStyle = C.faint;
ctx.fillText("ground, y = 0", 12, groundY + 14);

ctx.setLineDash([3, 4]);
ctx.strokeStyle = C.faint;
ctx.beginPath(); ctx.moveTo(10, Y(h0)); ctx.lineTo(W - 10, Y(h0)); ctx.stroke();
ctx.beginPath(); ctx.moveTo(10, Y(peak)); ctx.lineTo(W - 10, Y(peak)); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.faint;
ctx.fillText("release  " + h0.toFixed(0) + " m", W * 0.58, Y(h0) - 5);
ctx.fillText("peak  " + peak.toFixed(1) + " m", W * 0.58, Y(peak) - 5);

/* strobe: one dot every 0.2 s, equal time steps */
ctx.fillStyle = C.figure;
for (var s = 0; s <= tt + 1e-9; s += 0.2) {
  var ys = h0 + v0 * s - 0.5 * g * s * s;
  if (ys < 0) { continue; }
  ctx.beginPath(); ctx.arc(cx - 26, Y(ys), 2.5, 0, Math.PI * 2); ctx.fill();
}
ctx.fillStyle = C.faint;
ctx.fillText("strobe every 0.2 s", 10, pad - 8);

/* the ball */
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(cx, Y(y), 6, 0, Math.PI * 2); ctx.fill();

/* velocity arrow */
var av = v * 2.2;
if (Math.abs(av) > 60) { av = av > 0 ? 60 : -60; }
var y0p = Y(y), y1p = Y(y) - av;
ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
ctx.beginPath(); ctx.moveTo(cx, y0p); ctx.lineTo(cx, y1p); ctx.stroke();
var dir = av >= 0 ? 1 : -1;
ctx.beginPath();
ctx.moveTo(cx, y1p);
ctx.lineTo(cx - 4, y1p + dir * 7);
ctx.lineTo(cx + 4, y1p + dir * 7);
ctx.closePath();
ctx.fillStyle = C.accent; ctx.fill();
ctx.fillStyle = C.ink;
ctx.fillText("v = " + v.toFixed(1) + " m/s", cx + 10, y1p + 4);

/* gravity arrow, always down, always the same length */
var gx = W - 52;
ctx.strokeStyle = C.figure; ctx.lineWidth = 2;
ctx.beginPath(); ctx.moveTo(gx, H * 0.34); ctx.lineTo(gx, H * 0.34 + 34); ctx.stroke();
ctx.beginPath();
ctx.moveTo(gx, H * 0.34 + 41);
ctx.lineTo(gx - 4, H * 0.34 + 34);
ctx.lineTo(gx + 4, H * 0.34 + 34);
ctx.closePath();
ctx.fillStyle = C.figure; ctx.fill();
ctx.fillStyle = C.ink;
ctx.fillText("a = g down", gx - 14, H * 0.34 - 6);

out.note = "t = " + tt.toFixed(2) + " s, y = " + y.toFixed(1) + " m, v = " + v.toFixed(1) +
  " m/s  |  peak " + peak.toFixed(1) + " m, lands at t = " + tf.toFixed(2) + " s";
